"""Currículo inicial de Capricornio Plus.

Contenido original, estructurado para aprendizaje progresivo. Las rutas son material
educativo de partida; no sustituyen prácticas, proyectos ni evaluación docente.
"""

LESSONS = [
    # Fundamentos de programación
    {"id":"prog-01","area":"Fundamentos de programación","module":"Pensamiento computacional","title":"Algoritmos y pasos","level":"Principiante","objective":"Describir una solución como una secuencia ordenada de pasos.","content":"Un algoritmo es una secuencia finita y ordenada de instrucciones para resolver un problema. Antes de programar, identifica la entrada, el proceso y la salida. Los pasos deben ser claros, no ambiguos y terminar.","example":"Problema: preparar una taza de té. Entrada: agua y té. Proceso: calentar agua, poner la bolsa, esperar. Salida: té preparado.","question":"¿Qué describe mejor un algoritmo?","options":[{"value":"a","label":"Una secuencia ordenada de pasos para resolver un problema"},{"value":"b","label":"Una marca de computador"},{"value":"c","label":"Un lenguaje exclusivo de páginas web"}],"correct":"a","feedback":"Un algoritmo organiza los pasos para obtener un resultado.","skill":"programacion.algoritmos"},
    {"id":"prog-02","area":"Fundamentos de programación","module":"Pensamiento computacional","title":"Variables y tipos de datos","level":"Principiante","objective":"Reconocer variables y datos básicos.","content":"Una variable es un nombre asociado a un valor que un programa puede consultar o cambiar. Los tipos básicos incluyen enteros, decimales, texto y valores booleanos (verdadero o falso). El tipo ayuda a definir qué operaciones tienen sentido.","example":"nombre = 'Ana'\nedad = 20\nactivo = True","question":"¿Qué tipo de dato representa normalmente 20?","options":[{"value":"a","label":"Texto"},{"value":"b","label":"Entero"},{"value":"c","label":"Booleano"}],"correct":"b","feedback":"20 es un número entero; '20' entre comillas sería texto.","skill":"programacion.variables"},
    {"id":"prog-03","area":"Fundamentos de programación","module":"Control de flujo","title":"Condiciones y ciclos","level":"Principiante","objective":"Distinguir decisiones y repeticiones en un programa.","content":"Una condición permite elegir entre caminos según una expresión lógica. Un ciclo repite instrucciones: for suele recorrer una colección o rango; while continúa mientras una condición sea verdadera. Evita ciclos while cuya condición nunca cambie.","example":"for numero in range(1, 4):\n    print(numero)\n# Muestra 1, 2 y 3","question":"¿Qué estructura repite instrucciones mientras una condición sea verdadera?","options":[{"value":"a","label":"if"},{"value":"b","label":"while"},{"value":"c","label":"import"}],"correct":"b","feedback":"while evalúa la condición antes de cada repetición.","skill":"programacion.control"},
    # Software
    {"id":"soft-01","area":"Desarrollo de software y programación","module":"Construcción de software","title":"Del problema al requisito","level":"Principiante","objective":"Convertir una necesidad en un requisito verificable.","content":"Un requisito expresa qué necesita un usuario o qué condición debe cumplir el sistema. Un buen requisito es claro, verificable y evita mezclar varias necesidades. Pregunta quién lo necesita, para qué y cómo sabremos que funciona.","example":"Requisito: el sistema permitirá que una persona restablezca su contraseña mediante un enlace temporal enviado a su correo.","question":"¿Cuál requisito es más verificable?","options":[{"value":"a","label":"La aplicación debe ser bonita"},{"value":"b","label":"La pantalla de inicio debe cargar en menos de 2 segundos en la red de prueba definida"},{"value":"c","label":"Todo debe funcionar perfecto"}],"correct":"b","feedback":"Define una medida y una condición para comprobar el resultado.","skill":"software.requisitos"},
    {"id":"soft-02","area":"Desarrollo de software y programación","module":"Construcción de software","title":"Funciones y modularidad","level":"Principiante","objective":"Explicar por qué dividir un programa en funciones facilita su mantenimiento.","content":"Una función agrupa instrucciones con una responsabilidad concreta. Puede recibir parámetros y devolver un resultado. Dividir un programa en funciones reduce duplicación, facilita pruebas y permite cambiar una parte sin reescribir todo.","example":"def calcular_total(precio, cantidad):\n    return precio * cantidad","question":"¿Qué ventaja ofrece una función pequeña y enfocada?","options":[{"value":"a","label":"Facilita reutilizar y probar una responsabilidad"},{"value":"b","label":"Hace innecesarias las pruebas"},{"value":"c","label":"Impide usar parámetros"}],"correct":"a","feedback":"Las funciones enfocadas mejoran reutilización y mantenibilidad.","skill":"software.funciones"},
    {"id":"soft-03","area":"Desarrollo de software y programación","module":"Calidad de software","title":"Pruebas y depuración","level":"Principiante","objective":"Diferenciar probar, depurar y corregir.","content":"Una prueba compara el comportamiento del programa con un resultado esperado. Depurar consiste en localizar la causa de un comportamiento incorrecto. Un caso de prueba debe indicar entradas, acción y resultado esperado; incluye casos normales y límites.","example":"Para una función que divide, prueba 8/2 y también el caso divisor igual a cero.","question":"¿Qué describe un caso de prueba?","options":[{"value":"a","label":"Solo el nombre del desarrollador"},{"value":"b","label":"Entradas, acción y resultado esperado"},{"value":"c","label":"Una captura sin contexto"}],"correct":"b","feedback":"Un caso reproducible permite comprobar el comportamiento.","skill":"software.pruebas"},
    # Web
    {"id":"web-01","area":"Desarrollo web","module":"Fundamentos web","title":"HTML: estructura semántica","level":"Principiante","objective":"Identificar la función de HTML y sus elementos semánticos.","content":"HTML describe la estructura y el significado del contenido. Usa elementos como header, nav, main, section, article y footer para dar contexto. Los encabezados deben seguir una jerarquía lógica y las imágenes informativas necesitan texto alternativo.","example":"<main>\n  <h1>Mi página</h1>\n  <p>Contenido principal.</p>\n</main>","question":"¿Para qué sirve principalmente HTML?","options":[{"value":"a","label":"Definir la estructura y el significado del contenido"},{"value":"b","label":"Administrar usuarios del servidor"},{"value":"c","label":"Guardar contraseñas"}],"correct":"a","feedback":"HTML estructura el contenido; CSS lo presenta y JavaScript añade comportamiento.","skill":"web.html"},
    {"id":"web-02","area":"Desarrollo web","module":"Fundamentos web","title":"CSS: diseño adaptable","level":"Principiante","objective":"Comprender selectores, reglas y diseño adaptable.","content":"CSS controla la presentación mediante reglas formadas por selector y declaraciones. Flexbox y Grid ayudan a distribuir elementos. Las media queries permiten ajustar el diseño a pantallas distintas; prioriza legibilidad, contraste y navegación con teclado.","example":".contenedor {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));\n  gap: 1rem;\n}","question":"¿Qué herramienta permite adaptar estilos según el ancho de pantalla?","options":[{"value":"a","label":"Una media query"},{"value":"b","label":"Una clave primaria"},{"value":"c","label":"Un bucle SQL"}],"correct":"a","feedback":"Las media queries aplican estilos según características del dispositivo o viewport.","skill":"web.css"},
    {"id":"web-03","area":"Desarrollo web","module":"Interactividad","title":"JavaScript y el DOM","level":"Principiante","objective":"Explicar cómo JavaScript responde a eventos en una página.","content":"JavaScript permite añadir comportamiento a una página. El DOM representa el documento como objetos que el código puede consultar y modificar. Los eventos, como click o submit, permiten reaccionar a acciones; valida datos en el servidor aunque también valides en el navegador.","example":"document.querySelector('button').addEventListener('click', () => {\n  console.log('Botón activado');\n});","question":"¿Qué permite addEventListener?","options":[{"value":"a","label":"Escuchar un evento y ejecutar una función"},{"value":"b","label":"Crear una tabla SQL"},{"value":"c","label":"Cambiar el sistema operativo"}],"correct":"a","feedback":"El listener conecta un evento con el código que debe ejecutarse.","skill":"web.javascript"},
    # Ciberseguridad
    {"id":"cyber-01","area":"Ciberseguridad","module":"Fundamentos de seguridad","title":"Confidencialidad, integridad y disponibilidad","level":"Principiante","objective":"Reconocer los tres objetivos clásicos de seguridad de la información.","content":"La tríada CIA resume tres objetivos: confidencialidad (solo accede quien está autorizado), integridad (la información no se altera indebidamente) y disponibilidad (los servicios están accesibles cuando se necesitan). Un control puede apoyar uno o varios objetivos.","example":"Cifrar un archivo protege su confidencialidad; una copia de respaldo ayuda a recuperar disponibilidad.","question":"¿Qué objetivo busca evitar modificaciones no autorizadas?","options":[{"value":"a","label":"Integridad"},{"value":"b","label":"Disponibilidad"},{"value":"c","label":"Diseño visual"}],"correct":"a","feedback":"La integridad protege la exactitud y consistencia de la información.","skill":"ciberseguridad.triada"},
    {"id":"cyber-02","area":"Ciberseguridad","module":"Protección de cuentas","title":"Contraseñas y autenticación multifactor","level":"Principiante","objective":"Aplicar prácticas básicas de autenticación segura.","content":"Usa contraseñas largas y únicas, preferiblemente generadas y guardadas en un gestor. La autenticación multifactor añade una prueba adicional, por ejemplo una llave física o una aplicación autenticadora. Nunca compartas códigos de un solo uso.","example":"Una frase larga y exclusiva para cada servicio es preferible a reutilizar una clave corta.","question":"¿Qué reduce el impacto de que una contraseña se filtre?","options":[{"value":"a","label":"Reutilizarla en todas las cuentas"},{"value":"b","label":"Usar una contraseña única y MFA"},{"value":"c","label":"Enviar el código MFA por chat"}],"correct":"b","feedback":"La unicidad limita el efecto de una filtración y MFA añade otra barrera.","skill":"ciberseguridad.autenticacion"},
    {"id":"cyber-03","area":"Ciberseguridad","module":"Amenazas comunes","title":"Phishing y verificación","level":"Principiante","objective":"Detectar señales de mensajes fraudulentos y responder con seguridad.","content":"El phishing intenta engañar para obtener datos o provocar acciones. Desconfía de urgencias, enlaces inesperados, remitentes parecidos al real y archivos no solicitados. Verifica por un canal independiente; no uses el enlace del mensaje sospechoso.","example":"Si un correo dice que tu cuenta será bloqueada, abre la aplicación oficial escribiendo su dirección tú misma.","question":"¿Qué haces ante un enlace inesperado que solicita tu contraseña?","options":[{"value":"a","label":"Abrirlo rápidamente"},{"value":"b","label":"Verificar por un canal oficial independiente"},{"value":"c","label":"Compartirlo con tus contactos"}],"correct":"b","feedback":"La verificación independiente evita seguir el canal controlado por el atacante.","skill":"ciberseguridad.phishing"},
    # Datos
    {"id":"data-01","area":"Análisis de datos","module":"Fundamentos de datos","title":"Tipos y calidad de datos","level":"Principiante","objective":"Identificar datos estructurados y problemas básicos de calidad.","content":"Los datos pueden ser numéricos, categóricos, fechas o texto. Antes de analizarlos revisa valores faltantes, duplicados, unidades, formatos y errores. Una conclusión solo es tan confiable como los datos y el proceso que la sustentan.","example":"En una columna de edades, 25, '25 años' y -300 requieren normalización o revisión.","question":"¿Qué conviene revisar antes de calcular un promedio?","options":[{"value":"a","label":"Valores faltantes, unidades y errores"},{"value":"b","label":"El color de las celdas"},{"value":"c","label":"Solo el nombre del archivo"}],"correct":"a","feedback":"La limpieza evita que errores distorsionen el resultado.","skill":"datos.calidad"},
    {"id":"data-02","area":"Análisis de datos","module":"Exploración","title":"Promedio, mediana y distribución","level":"Principiante","objective":"Elegir medidas descriptivas según la distribución.","content":"El promedio suma los valores y divide por la cantidad; puede verse afectado por valores extremos. La mediana es el valor central al ordenar los datos y suele representar mejor distribuciones sesgadas. Observa también rango y distribución.","example":"Para 2, 3, 3, 4, 100, el promedio es 22.4 y la mediana es 3.","question":"¿Qué medida es menos sensible a un valor extremo?","options":[{"value":"a","label":"La mediana"},{"value":"b","label":"El promedio"},{"value":"c","label":"La suma"}],"correct":"a","feedback":"La mediana depende de la posición central, no de la magnitud del extremo.","skill":"datos.estadistica"},
    {"id":"data-03","area":"Análisis de datos","module":"Comunicación","title":"Gráficos y conclusiones","level":"Principiante","objective":"Seleccionar una visualización y comunicar límites de un análisis.","content":"Usa barras para comparar categorías, líneas para evolución temporal y dispersión para explorar relaciones entre variables numéricas. Un gráfico debe mostrar unidades y contexto. Correlación no demuestra causalidad: pueden existir variables adicionales.","example":"Una línea de ventas por mes permite ver tendencias; una barra compara ventas entre regiones.","question":"¿Qué gráfico suele ser adecuado para mostrar una serie mensual?","options":[{"value":"a","label":"Gráfico de líneas"},{"value":"b","label":"Diagrama de red sin ejes"},{"value":"c","label":"Una imagen decorativa"}],"correct":"a","feedback":"Las líneas ayudan a seguir cambios a lo largo del tiempo.","skill":"datos.visualizacion"},
    # Bases de datos
    {"id":"db-01","area":"Bases de datos","module":"Modelo relacional","title":"Tablas, filas y columnas","level":"Principiante","objective":"Interpretar la estructura básica de una tabla relacional.","content":"Una tabla organiza registros en filas y atributos en columnas. Cada columna tiene un tipo de dato. Una clave primaria identifica cada fila de forma única; evita usar datos personales cambiantes como identificador cuando exista una clave técnica adecuada.","example":"usuarios(id, nombre, correo). id puede ser la clave primaria.","question":"¿Qué garantiza una clave primaria?","options":[{"value":"a","label":"Identificar de forma única cada registro"},{"value":"b","label":"Cifrar automáticamente toda la tabla"},{"value":"c","label":"Ordenar siempre por apellido"}],"correct":"a","feedback":"La clave primaria identifica cada fila sin duplicados ni valores nulos.","skill":"bases_datos.modelo"},
    {"id":"db-02","area":"Bases de datos","module":"Consultas SQL","title":"SELECT y WHERE","level":"Principiante","objective":"Leer una consulta SQL de selección y filtrado.","content":"SELECT indica qué columnas recuperar y FROM indica la tabla. WHERE filtra filas según una condición. Usa parámetros en consultas desde aplicaciones para evitar inyección SQL; no concatenes directamente entradas del usuario.","example":"SELECT nombre, correo\nFROM usuarios\nWHERE activo = 1;","question":"¿Qué cláusula filtra las filas?","options":[{"value":"a","label":"WHERE"},{"value":"b","label":"FROM"},{"value":"c","label":"ORDER"}],"correct":"a","feedback":"WHERE limita el resultado a las filas que cumplen la condición.","skill":"bases_datos.sql"},
    {"id":"db-03","area":"Bases de datos","module":"Integridad y relaciones","title":"Relaciones y claves foráneas","level":"Principiante","objective":"Explicar cómo una clave foránea conecta tablas.","content":"Una clave foránea referencia una clave de otra tabla y ayuda a mantener integridad referencial. Una relación uno a muchos permite que un registro padre tenga varios registros hijos. Diseñar relaciones evita duplicar información sin control.","example":"pedidos.usuario_id referencia usuarios.id; cada pedido pertenece a un usuario.","question":"¿Qué representa una clave foránea?","options":[{"value":"a","label":"Una referencia a un registro de otra tabla"},{"value":"b","label":"Una contraseña del servidor"},{"value":"c","label":"Un gráfico estadístico"}],"correct":"a","feedback":"La clave foránea vincula registros y protege la consistencia entre tablas.","skill":"bases_datos.relaciones"},
    # IA
    {"id":"ai-01","area":"Inteligencia artificial","module":"Conceptos de IA","title":"Qué es y qué no es un modelo","level":"Principiante","objective":"Distinguir modelo, datos y tarea de aprendizaje automático.","content":"Un modelo de aprendizaje automático aprende patrones a partir de datos para realizar una tarea, como clasificar o predecir. No comprende necesariamente el mundo ni garantiza resultados correctos. Su rendimiento depende de datos, objetivo y evaluación.","example":"Un clasificador puede estimar si un correo es spam usando ejemplos etiquetados.","question":"¿Qué aprende un modelo supervisado?","options":[{"value":"a","label":"Patrones a partir de ejemplos con etiquetas"},{"value":"b","label":"La contraseña del usuario"},{"value":"c","label":"Reglas infalibles sin datos"}],"correct":"a","feedback":"El aprendizaje supervisado usa ejemplos acompañados de la respuesta esperada.","skill":"ia.conceptos"},
    {"id":"ai-02","area":"Inteligencia artificial","module":"Datos y entrenamiento","title":"Entrenamiento, validación y prueba","level":"Principiante","objective":"Explicar por qué se separan los datos al entrenar un modelo.","content":"El conjunto de entrenamiento ajusta el modelo. Validación ayuda a elegir configuraciones. Prueba estima el rendimiento final con datos no usados durante el ajuste. Mezclar los conjuntos puede producir fuga de datos y métricas engañosas.","example":"Separa registros antes de normalizar o seleccionar variables para evitar que información del conjunto de prueba influya en el entrenamiento.","question":"¿Para qué se reserva un conjunto de prueba?","options":[{"value":"a","label":"Estimar el rendimiento final en datos no usados para ajustar"},{"value":"b","label":"Aumentar artificialmente la precisión"},{"value":"c","label":"Guardar las contraseñas"}],"correct":"a","feedback":"La prueba ofrece una evaluación más independiente del modelo.","skill":"ia.evaluacion"},
    {"id":"ai-03","area":"Inteligencia artificial","module":"Evaluación responsable","title":"Sesgo y métricas","level":"Principiante","objective":"Reconocer límites de las métricas y posibles sesgos.","content":"La exactitud puede ocultar fallos cuando las clases están desbalanceadas. Precisión y recall ayudan a entender distintos tipos de error. Evalúa resultados por grupos relevantes, documenta límites y evita usar un modelo en decisiones sensibles sin controles adecuados.","example":"Si solo 1 de cada 100 casos es fraude, un modelo que siempre dice 'no fraude' tendría 99% de exactitud y sería inútil para detectar fraude.","question":"¿Por qué la exactitud puede ser engañosa en clases desbalanceadas?","options":[{"value":"a","label":"Puede ser alta aunque el modelo ignore la clase minoritaria"},{"value":"b","label":"Siempre mide causalidad"},{"value":"c","label":"No usa datos"}],"correct":"a","feedback":"Revisa métricas por clase, matriz de confusión y consecuencias de cada error.","skill":"ia.etica"},
    # Redes y sistemas
    {"id":"net-01","area":"Redes y sistemas","module":"Fundamentos de redes","title":"Dispositivos y direcciones IP","level":"Principiante","objective":"Comprender para qué sirve una dirección IP en una red.","content":"Una red conecta dispositivos para intercambiar datos. Una dirección IP identifica una interfaz dentro de una red y permite encaminar paquetes. IP privada y pública cumplen funciones distintas; una dirección puede cambiar según la configuración.","example":"En una red doméstica, el router suele asignar direcciones privadas como 192.168.1.10 mediante DHCP.","question":"¿Qué función cumple una dirección IP?","options":[{"value":"a","label":"Identificar una interfaz para comunicarla en una red"},{"value":"b","label":"Cifrar por sí sola el tráfico"},{"value":"c","label":"Identificar la marca del monitor"}],"correct":"a","feedback":"La IP permite direccionar tráfico; no cifra por sí misma la comunicación.","skill":"redes.ip"},
    {"id":"net-02","area":"Redes y sistemas","module":"Servicios de red","title":"DNS, DHCP y HTTP","level":"Principiante","objective":"Diferenciar servicios comunes de red.","content":"DNS traduce nombres de dominio a registros como direcciones IP. DHCP asigna configuración de red automáticamente. HTTP define intercambios web y HTTPS añade protección criptográfica mediante TLS. Son servicios distintos y complementarios.","example":"Al abrir un dominio, el equipo puede consultar DNS antes de conectarse al servidor web por HTTPS.","question":"¿Qué servicio ayuda a resolver un nombre de dominio?","options":[{"value":"a","label":"DNS"},{"value":"b","label":"DHCP"},{"value":"c","label":"GPIO"}],"correct":"a","feedback":"DNS permite localizar servicios mediante nombres legibles.","skill":"redes.servicios"},
    {"id":"net-03","area":"Redes y sistemas","module":"Sistemas operativos","title":"Procesos, archivos y permisos","level":"Principiante","objective":"Identificar funciones básicas de un sistema operativo.","content":"El sistema operativo administra procesos, memoria, dispositivos, archivos y permisos. Un proceso es un programa en ejecución. Los permisos controlan quién puede leer, modificar o ejecutar recursos; aplica el principio de mínimo privilegio.","example":"En Linux, ls -l muestra permisos; chmod cambia permisos de archivos.","question":"¿Qué principio recomienda conceder solo los permisos necesarios?","options":[{"value":"a","label":"Mínimo privilegio"},{"value":"b","label":"Acceso universal"},{"value":"c","label":"Duplicación de permisos"}],"correct":"a","feedback":"El mínimo privilegio reduce el impacto de errores y compromisos.","skill":"sistemas.permisos"},
    # POO
    {"id":"oop-01","area":"Programación orientada a objetos","module":"Modelado con objetos","title":"Clases e instancias","level":"Principiante","objective":"Diferenciar una clase de un objeto.","content":"Una clase define una estructura y comportamientos comunes. Un objeto es una instancia concreta de esa clase con sus propios valores. Modela conceptos del dominio sin convertir cada dato en una clase innecesaria.","example":"class Persona:\n    def __init__(self, nombre):\n        self.nombre = nombre\n\nana = Persona('Ana')","question":"¿Qué es una instancia?","options":[{"value":"a","label":"Un objeto creado a partir de una clase"},{"value":"b","label":"Un archivo ejecutable"},{"value":"c","label":"Una consulta SQL"}],"correct":"a","feedback":"La instancia es el objeto concreto construido desde la clase.","skill":"poo.clases"},
    {"id":"oop-02","area":"Programación orientada a objetos","module":"Modelado con objetos","title":"Atributos y métodos","level":"Principiante","objective":"Reconocer estado y comportamiento de un objeto.","content":"Los atributos representan datos o estado de un objeto. Los métodos representan operaciones relacionadas con ese objeto. Mantener juntos los datos y las operaciones pertinentes ayuda a expresar responsabilidades.","example":"Una cuenta puede tener el atributo saldo y métodos depositar() y retirar().","question":"¿Qué representa normalmente un método?","options":[{"value":"a","label":"Un comportamiento u operación del objeto"},{"value":"b","label":"Solo un valor constante"},{"value":"c","label":"Una dirección IP"}],"correct":"a","feedback":"Los métodos implementan comportamientos asociados a la clase.","skill":"poo.metodos"},
    {"id":"oop-03","area":"Programación orientada a objetos","module":"Diseño responsable","title":"Encapsulación y composición","level":"Principiante","objective":"Explicar cómo proteger el estado y combinar responsabilidades.","content":"La encapsulación controla cómo se modifica el estado de un objeto mediante una interfaz. La composición construye objetos complejos usando otros objetos. Prefiere relaciones claras y composición cuando evita jerarquías de herencia rígidas.","example":"Pedido contiene una lista de LineaPedido; cada línea conoce producto y cantidad.","question":"¿Qué busca la encapsulación?","options":[{"value":"a","label":"Controlar el acceso y los cambios del estado"},{"value":"b","label":"Hacer públicos todos los datos"},{"value":"c","label":"Evitar usar métodos"}],"correct":"a","feedback":"La encapsulación protege invariantes y ofrece una interfaz controlada.","skill":"poo.encapsulacion"}
]

AREAS = list(dict.fromkeys(item["area"] for item in LESSONS))
LESSONS_BY_ID = {item["id"]: item for item in LESSONS}
